using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
partial class UsageWidget {
 string lastUsageLink="",lastHistoryTip="";
 List<DayUsage> HistoryRows(){var d=Selected==null?null:Selected.Data;return DailyHistory.Rows(d==null?null:d.DailyTokens,d==null?null:d.LocalDailyTokens,d==null?null:d.TodayLocalTokens,DateTime.Today,historyDays);}
 string DayText(DayUsage row){return row.Day.ToString("MM/dd")+(row.Day==DateTime.Today?" · 오늘":"")+" · "+(row.Tokens.HasValue?row.Tokens.Value.ToString("N0")+" 토큰":"미집계")+" · "+(row.Local?"이 PC 참고":"서버 집계");}
 void OpenUsage(){lastUsageLink=AccountExtras.UsageUrl;if(AppPaths.VerifyOnly)return;try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(AccountExtras.UsageUrl){UseShellExecute=true});}catch{MessageBox.Show("브라우저에서 ChatGPT의 설정 → 사용량을 열어 주세요.","사용량 페이지");}}
 void PaintDailyGraph(Graphics g,float y,bool detail){var rows=HistoryRows();string alias=Selected==null?"":Selected.Entry.Alias;BoardDraw.Text(g,detail?alias+" · 일별 사용량":"최근 토큰 · "+alias,new RectangleF(20,y,204,29),detail?18:14,theme.Ink,true);
  rangeFive=new RectangleF(242,y+1,51,25);rangeTen=new RectangleF(298,y+1,57,25);foreach(var item in new[]{new{Bounds=rangeFive,Days=5},new{Bounds=rangeTen,Days=10}}){BoardDraw.Box(g,item.Bounds,historyDays==item.Days?theme.Tint:theme.Surface,7,historyDays==item.Days?theme.Accent:theme.Line);BoardDraw.Text(g,item.Days+"일",item.Bounds,11,historyDays==item.Days?theme.Accent:theme.Muted,true,false,true);}
  BoardDraw.Text(g,"최근 "+historyDays+"일 · 미집계는 0과 구분합니다.",new RectangleF(20,y+30,335,22),10,theme.Muted);
  var plot=new RectangleF(20,y+59,335,132);BoardDraw.Box(g,plot,theme.Surface,9,theme.Line);float baseline=plot.Bottom-24,cell=(plot.Width-12)/rows.Count;long max=rows.Where(x=>x.Tokens.HasValue).Select(x=>x.Tokens.Value).DefaultIfEmpty(0).Max();historyHits.Clear();
  for(int i=0;i<rows.Count;i++){var row=rows[i];float x=plot.X+6+i*cell,w=Math.Min(historyDays==10?17:32,cell-10),center=x+cell/2;historyHits.Add(new RectangleF(x,plot.Y+4,cell,plot.Height-4));if(i==hoveredHistory)BoardDraw.Box(g,new RectangleF(x+1,plot.Y+3,cell-2,plot.Height-6),theme.Tint,5);float h=row.Tokens.HasValue&&max>0?(float)(84.0*row.Tokens.Value/max):0;
   if(row.Tokens.HasValue){if(row.Tokens>0)BoardDraw.Box(g,new RectangleF(center-w/2,baseline-Math.Max(2,h),w,Math.Max(2,h)),row.Local?theme.Accent:theme.Quota(65),Math.Min(4,Math.Max(1,h/2)));else using(var pen=new Pen(theme.Muted,1.5f))g.DrawLine(pen,center-w/2,baseline,center+w/2,baseline);BoardDraw.Text(g,Compact(row.Tokens.Value),new RectangleF(x-2,baseline-Math.Max(0,h)-20,cell+4,18),historyDays==10?9:10,theme.Ink,true,false,true);}
   else{using(var pen=new Pen(theme.Muted,1)){pen.DashStyle=DashStyle.Dash;g.DrawRectangle(pen,center-w/2,baseline-23,w,23);}BoardDraw.Text(g,"미집계",new RectangleF(x-2,baseline-44,cell+4,19),9,theme.Muted,false,false,true);}
   BoardDraw.Text(g,row.Day.ToString("MM/dd"),new RectangleF(x-3,baseline+3,cell+6,19),historyDays==10?9:10,row.Day==DateTime.Today?theme.Accent:theme.Muted,false,false,true);
  }
  int at=hoveredHistory>=0&&hoveredHistory<rows.Count?hoveredHistory:rows.Count-1;BoardDraw.Text(g,DayText(rows[at]),new RectangleF(20,y+199,335,24),11,theme.Ink);BoardDraw.Text(g,"PC 참고값은 다른 기기 사용량을 포함하지 않습니다.",new RectangleF(20,y+224,detail?335:248,22),9,theme.Muted);historyDetails=new RectangleF(277,y+224,78,24);if(!detail)BoardDraw.Text(g,"자세히 →",historyDetails,11,theme.Accent,false,true);
 }
 void PaintHistory(Graphics g){PaintDailyGraph(g,10,true);var rows=HistoryRows().AsEnumerable().Reverse().ToArray();for(int i=0;i<rows.Length;i++){float y=274+i*39;var row=rows[i];BoardDraw.Text(g,row.Day.ToString("MM/dd")+(row.Day==DateTime.Today?" · 오늘":""),new RectangleF(20,y,123,24),12,theme.Ink);BoardDraw.Text(g,row.Tokens.HasValue?row.Tokens.Value.ToString("N0"):"미집계",new RectangleF(152,y,139,24),14,theme.Ink,true,true);BoardDraw.Text(g,row.Local?"PC 참고":"서버",new RectangleF(299,y,56,24),9,theme.Muted,false,true);BoardDraw.Line(g,y+33,375,theme.Line);}}
 AccountState UsageHit(PointF p){if(tab!="한도")return null;for(int i=0;i<states.Count;i++){float top=4+i*202;if(new RectangleF(213,top+177,142,23).Contains(p)||new RectangleF(278,top+155,77,24).Contains(p))return states[i];}return null;}
 void BoardClick(object sender,MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;var p=new PointF(e.X/uiScale,e.Y/uiScale);if(rangeFive.Contains(p)||rangeTen.Contains(p)){historyDays=rangeTen.Contains(p)?10:5;hoveredHistory=-1;SaveSettings();RebuildBody();return;}var usage=UsageHit(p);if(usage!=null){selectedId=usage.Entry.Id;SaveSettings();OpenUsage();return;}for(int i=0;i<historyHits.Count;i++)if(historyHits[i].Contains(p)){hoveredHistory=i;board.Invalidate();return;}if(tab=="기록")return;if(historyDetails.Contains(p)){SelectTab("기록");return;}int row=(int)((p.Y-4)/202);if(p.Y>=4&&row>=0&&row<states.Count){selectedId=states[row].Entry.Id;hoveredHistory=-1;SaveSettings();if(p.X>316&&p.Y-row*202<42)AccountMenu(states[row],new Point(e.X,e.Y));board.Invalidate();}}
 void BoardHover(object sender,MouseEventArgs e){var p=new PointF(e.X/uiScale,e.Y/uiScale);int next=historyHits.FindIndex(r=>r.Contains(p));string text="";var usage=UsageHit(p);if(usage!=null){var d=usage.Data;text="공식 사용량 페이지 열기 · 브라우저에서도 해당 계정으로 로그인해 주세요.";if(d!=null&&d.ResetCredits.HasValue)text="초기화권 "+d.ResetCredits.Value+"개 · 확인 "+d.CreditsUpdated.ToString("MM/dd HH:mm")+(d.CreditsError!=null?" · 이전 조회":"")+"\n"+text;}else if(next>=0){var rows=HistoryRows();if(next<rows.Count)text=DayText(rows[next]);}board.Cursor=next>=0||usage!=null||rangeFive.Contains(p)||rangeTen.Contains(p)||historyDetails.Contains(p)?Cursors.Hand:Cursors.Default;if(text!=lastHistoryTip){lastHistoryTip=text;tips.SetToolTip(board,text);}if(next!=hoveredHistory){hoveredHistory=next;board.Invalidate();}}
}
